-- تولیدشده توسط scripts/gen-seed.mjs. دستی ویرایش نکنید؛ data/real-catalog.json را عوض و دوباره تولید کنید.
-- ⚠ قبل از اجرا نرخ تبدیل دلار به تومان را در v_rate بنویسید (ستون‌های تومانی سبد و سفارش هنوز لازم‌اند). نرخ عمداً خالی است.
-- آگهی‌های بدون قیمت دلاری (مثل TUF) وارد دیتابیس نمی‌شوند.
begin;
do $seed$
declare v_rate numeric := null; -- عدد نرخ روز را خودتان اینجا بنویسید
begin
  if v_rate is null or v_rate <= 0 then raise exception 'SET_V_RATE: نرخ دلار به تومان را در v_rate بنویسید'; end if;
  -- انحصاری: همهٔ محصولات قبلی غیرفعال می‌شوند (حذف نمی‌شوند)
  update public.products set is_active = false where is_active;
  insert into public.categories (slug, name, sort) select 'phones', 'گوشی موبایل', 1 where not exists (select 1 from public.categories where slug = 'phones');
  insert into public.categories (slug, name, sort) select 'gaming-laptops', 'لپ‌تاپ گیمینگ', 2 where not exists (select 1 from public.categories where slug = 'gaming-laptops');
  insert into public.categories (slug, name, sort) select 'laptops', 'لپ‌تاپ', 3 where not exists (select 1 from public.categories where slug = 'laptops');
  insert into public.categories (slug, name, sort) select 'satellite-internet', 'اینترنت ماهواره‌ای', 4 where not exists (select 1 from public.categories where slug = 'satellite-internet');
  insert into public.categories (slug, name, sort) select 'game-consoles', 'کنسول بازی', 5 where not exists (select 1 from public.categories where slug = 'game-consoles');
  -- Samsung Galaxy S26 Ultra 256GB
  update public.products set name='Samsung Galaxy S26 Ultra 256GB', description='گلکسی S26 Ultra پرچمدار سامسونگ در سال ۲۰۲۶ است با نمایشگر ۶٫۹ اینچی QHD+ Dynamic AMOLED 2X، نرخ نوسازی ۱ تا ۱۲۰ هرتز و قابلیت Privacy Display. پردازنده Snapdragon 8 Elite Gen 5 for Galaxy و رم ۱۲ گیگابایت دارد. دوربین اصلی ۲۰۰ مگاپیکسلی به‌همراه فوق‌عریض ۵۰ مگاپیکسل و دو تله‌فوتو (۵x با ۵۰ مگاپیکسل و ۳x با ۱۰ مگاپیکسل) و دوربین سلفی ۱۲ مگاپیکسلی. باتری ۵۰۰۰ میلی‌آمپرساعت با شارژ ۶۰ وات و قلم S Pen داخلی. نسخهٔ 256GB.', is_active=true, price_toman=round((139999 / 100.0) * v_rate), discount_percent=0, stock=10, price_usd_cents=139999, brand='Samsung', specs='{"display":"6.9 inch QHD+ Dynamic AMOLED 2X, 1-120Hz, Privacy Display","cpu":"Snapdragon 8 Elite Gen 5 for Galaxy","ram":"12GB","storage":"256GB","camera":"200MP main + 50MP ultra-wide + 50MP 5x + 10MP 3x","front_camera":"12MP","battery":"5000mAh, 60W wired / 25W wireless","pen":"S Pen built-in"}'::jsonb, price_checked_on='2026-10-11', source_url='https://www.techrepublic.com/article/news-samsung-galaxy-s26-price-hike-us/', price_note=null where slug='samsung-galaxy-s26-ultra-256gb';
  insert into public.products (slug, name, description, category_id, price_toman, discount_percent, stock, is_active, price_usd_cents, brand, specs, price_checked_on, source_url, price_note)
  select 'samsung-galaxy-s26-ultra-256gb', 'Samsung Galaxy S26 Ultra 256GB', 'گلکسی S26 Ultra پرچمدار سامسونگ در سال ۲۰۲۶ است با نمایشگر ۶٫۹ اینچی QHD+ Dynamic AMOLED 2X، نرخ نوسازی ۱ تا ۱۲۰ هرتز و قابلیت Privacy Display. پردازنده Snapdragon 8 Elite Gen 5 for Galaxy و رم ۱۲ گیگابایت دارد. دوربین اصلی ۲۰۰ مگاپیکسلی به‌همراه فوق‌عریض ۵۰ مگاپیکسل و دو تله‌فوتو (۵x با ۵۰ مگاپیکسل و ۳x با ۱۰ مگاپیکسل) و دوربین سلفی ۱۲ مگاپیکسلی. باتری ۵۰۰۰ میلی‌آمپرساعت با شارژ ۶۰ وات و قلم S Pen داخلی. نسخهٔ 256GB.', (select id from public.categories where slug='phones'), round((139999 / 100.0) * v_rate), 0, 10, true, 139999, 'Samsung', '{"display":"6.9 inch QHD+ Dynamic AMOLED 2X, 1-120Hz, Privacy Display","cpu":"Snapdragon 8 Elite Gen 5 for Galaxy","ram":"12GB","storage":"256GB","camera":"200MP main + 50MP ultra-wide + 50MP 5x + 10MP 3x","front_camera":"12MP","battery":"5000mAh, 60W wired / 25W wireless","pen":"S Pen built-in"}'::jsonb, '2026-10-11', 'https://www.techrepublic.com/article/news-samsung-galaxy-s26-price-hike-us/', null
  where not exists (select 1 from public.products where slug='samsung-galaxy-s26-ultra-256gb');
  delete from public.product_images where product_id = (select id from public.products where slug='samsung-galaxy-s26-ultra-256gb');
  insert into public.product_images (product_id, url, alt, sort) select id, '/products/samsung-galaxy-s26-ultra-1.webp', 'Galaxy S26 Ultra در چهار رنگ', 0 from public.products where slug='samsung-galaxy-s26-ultra-256gb';
  insert into public.product_images (product_id, url, alt, sort) select id, '/products/samsung-galaxy-s26-ultra-4.webp', 'Galaxy S26 Ultra در چهار رنگ، نمای دوم', 1 from public.products where slug='samsung-galaxy-s26-ultra-256gb';
  insert into public.product_images (product_id, url, alt, sort) select id, '/products/samsung-galaxy-s26-ultra-3.webp', 'Galaxy S26 Ultra مشکی با قلم، ۲۵۶ گیگابایت', 2 from public.products where slug='samsung-galaxy-s26-ultra-256gb';
  insert into public.product_images (product_id, url, alt, sort) select id, '/products/samsung-galaxy-s26-ultra-2.webp', 'Galaxy S26 Ultra با قلم S Pen', 3 from public.products where slug='samsung-galaxy-s26-ultra-256gb';
