  select 'apple-iphone-18-pro-max', 'Apple iPhone 18 Pro Max', 'آیفون ۱۸ پرو مکس با نمایشگر ۶٫۹ اینچی Super Retina XDR OLED با رزولوشن ۲۸۶۸ در ۱۳۲۰، ProMotion تا ۱۲۰ هرتز، Always-On و Dynamic Island. تراشهٔ A20 Pro (۲ نانومتر)، سیستم دوربین ۴۸ مگاپیکسلی Pro Fusion با اصلی، فوق‌عریض و تله‌فوتو، و سیستم‌عامل iOS 27. ظرفیت باتری بسته به نسخهٔ سیم‌کارت ۵٬۳۹۱ یا ۵٬۵۶۷ میلی‌آمپرساعت است و وزن گوشی ۲۴۹ گرم است. قیمت ذکرشده قیمت شروع است.', (select id from public.categories where slug='phones'), round((129900 / 100.0) * v_rate), 0, 10, true, 129900, 'Apple', '{"display":"6.9 inch Super Retina XDR OLED, 2868x1320, ProMotion up to 120Hz","cpu":"Apple A20 Pro","ram":"12GB","storage":"256GB / 512GB / 2TB","camera":"48MP Pro Fusion triple (main, ultra-wide, telephoto)","battery":"5391mAh (nano-SIM) / 5567mAh (eSIM only)","os":"iOS 27","weight":"249g"}'::jsonb, '2026-10-11', 'https://applescoop.org/story/which-iphone-should-you-buy-2026-every-model-compared', 'from'
