  update public.products set name='Apple iPhone Air', description='آیفون Air نازک‌ترین و سبک‌ترین آیفون است: ضخامت ۵٫۶۴ میلی‌متر و وزن ۱۶۵ گرم. نمایشگر ۶٫۵ اینچی Super Retina XDR OLED با رزولوشن ۲۷۳۶ در ۱۲۶۰ و ProMotion تا ۱۲۰ هرتز دارد. تراشهٔ A19 Pro با پردازندهٔ ۶ هسته‌ای و گرافیک ۵ هسته‌ای، یک دوربین ۴۸ مگاپیکسلی Fusion در پشت و دوربین سلفی ۱۸ مگاپیکسلی. حافظه از ۲۵۶ گیگابایت شروع می‌شود و فقط eSIM پشتیبانی می‌کند. نام رسمی محصول «iPhone Air» است و اپل مدلی با نام «iPhone 17 Air» عرضه نکرده. قیمت ذکرشده قیمت شروع پس از افزایش ۹ سپتامبر ۲۰۲۶ است.', is_active=true, price_toman=round((109900 / 100.0) * v_rate), discount_percent=0, stock=10, price_usd_cents=109900, brand='Apple', specs='{"display":"6.5 inch Super Retina XDR OLED, 2736x1260, ProMotion up to 120Hz","cpu":"Apple A19 Pro (6-core CPU, 5-core GPU)","storage":"256GB and up","camera":"48MP Fusion single rear camera","front_camera":"18MP","thickness":"5.64mm","weight":"165g","sim":"eSIM only"}'::jsonb, price_checked_on='2026-10-11', source_url='https://www.tomsguide.com/phones/iphones/iphone-17-pre-order-deals-heres-how-to-get-apples-new-phones-for-free', price_note='from' where slug='apple-iphone-air';
