  -- Xiaomi Redmi Note 14 5G
  update public.products set name='Xiaomi Redmi Note 14 5G', description='ردمی نوت ۱۴ 5G شیائومی با نمایشگر AMOLED ‏۶٫۶۷ اینچی، رزولوشن ۱۰۸۰×۲۴۰۰، نرخ نوسازی ۱۲۰ هرتز و روشنایی اوج ۲۱۰۰ نیت. پردازندهٔ MediaTek Dimensity 7025 Ultra، دوربین اصلی ۱۰۸ مگاپیکسلی با OIS به‌همراه فوق‌عریض ۸ و ماکرو ۲ مگاپیکسلی و دوربین سلفی ۲۰ مگاپیکسلی. باتری ۵۱۱۰ میلی‌آمپرساعت با شارژ ۴۵ وات، اندروید ۱۴ با HyperOS و مقاومت IP64. در نسخه‌های ۱۲۸، ۲۵۶ و ۵۱۲ گیگابایت عرضه شده است.', is_active=true, price_toman=round((23950 / 100.0) * v_rate), discount_percent=0, stock=12, price_usd_cents=23950, brand='Xiaomi', specs='{"display":"6.67 inch AMOLED, 1080x2400, 120Hz, 2100 nits peak","cpu":"MediaTek Dimensity 7025 Ultra (6 nm)","ram":"6GB / 8GB / 12GB","storage":"128GB / 256GB / 512GB","camera":"108MP main (OIS) + 8MP ultra-wide + 2MP macro","front_camera":"20MP","battery":"5110mAh, 45W","os":"Android 14 (HyperOS)","weight":"190 g","thickness":"8 mm","sim":"Dual Nano-SIM","body":"Gorilla Glass 5 front, plastic back and frame, IP64"}'::jsonb, price_checked_on='2026-10-12', source_url='https://m.gsmarena.com/xiaomi_redmi_note_14_5g_(global)-13615.php', price_note='approx' where slug='xiaomi-redmi-note-14-5g';
