  -- Xiaomi POCO X7
  update public.products set name='Xiaomi POCO X7', description='پوکو X7 شیائومی با نمایشگر AMOLED ‏۶٫۶۷ اینچی CrystalRes، رزولوشن ۱۲۲۰×۲۷۱۲، نرخ نوسازی ۱۲۰ هرتز و روشنایی اوج ۳۰۰۰ نیت. پردازندهٔ MediaTek Dimensity 7300 Ultra با گرافیک Mali-G615 MC2، دوربین اصلی ۵۰ مگاپیکسلی با OIS به‌همراه فوق‌عریض ۸ و ماکرو ۲ مگاپیکسلی و دوربین سلفی ۲۰ مگاپیکسلی. باتری ۵۱۱۰ میلی‌آمپرساعت با شارژ ۴۵ وات، اندروید ۱۴ با HyperOS، شیشهٔ Gorilla Glass Victus 2 و مقاومت IP68. در رنگ‌های نقره‌ای، سبز و مشکی-زرد و نسخه‌های ۱۲۸، ۲۵۶ و ۵۱۲ گیگابایت عرضه شده است. توجه: این مدل X7 معمولی است، نه X7 Pro.', is_active=true, price_toman=round((27500 / 100.0) * v_rate), discount_percent=0, stock=10, price_usd_cents=27500, brand='Xiaomi', specs='{"display":"6.67 inch CrystalRes AMOLED, 1220x2712, 120Hz, 3000 nits peak","cpu":"MediaTek Dimensity 7300 Ultra (4 nm)","gpu":"Mali-G615 MC2","ram":"8GB / 12GB","storage":"128GB / 256GB / 512GB","camera":"50MP main (OIS) + 8MP ultra-wide + 2MP macro","front_camera":"20MP","battery":"5110mAh, 45W","os":"Android 14 (HyperOS)","weight":"185.5 g (plastic) / 190 g (PU)","thickness":"8.4 mm / 8.6 mm","sim":"Dual SIM","body":"Gorilla Glass Victus 2 front, IP68"}'::jsonb, price_checked_on='2026-10-12', source_url='https://m.gsmarena.com/xiaomi_poco_x7-ampp-13604.php', price_note='approx' where slug='xiaomi-poco-x7';
  insert into public.products (slug, name, description, category_id, price_toman, discount_percent, stock, is_active, price_usd_cents, brand, specs, price_checked_on, source_url, price_note)
  select 'xiaomi-poco-x7', 'Xiaomi POCO X7', 'پوکو X7 شیائومی با نمایشگر AMOLED ‏۶٫۶۷ اینچی CrystalRes، رزولوشن ۱۲۲۰×۲۷۱۲، نرخ نوسازی ۱۲۰ هرتز و روشنایی اوج ۳۰۰۰ نیت. پردازندهٔ MediaTek Dimensity 7300 Ultra با گرافیک Mali-G615 MC2، دوربین اصلی ۵۰ مگاپیکسلی با OIS به‌همراه فوق‌عریض ۸ و ماکرو ۲ مگاپیکسلی و دوربین سلفی ۲۰ مگاپیکسلی. باتری ۵۱۱۰ میلی‌آمپرساعت با شارژ ۴۵ وات، اندروید ۱۴ با HyperOS، شیشهٔ Gorilla Glass Victus 2 و مقاومت IP68. در رنگ‌های نقره‌ای، سبز و مشکی-زرد و نسخه‌های ۱۲۸، ۲۵۶ و ۵۱۲ گیگابایت عرضه شده است. توجه: این مدل X7 معمولی است، نه X7 Pro.', (select id from public.categories where slug='phones'), round((27500 / 100.0) * v_rate), 0, 10, true, 27500, 'Xiaomi', '{"display":"6.67 inch CrystalRes AMOLED, 1220x2712, 120Hz, 3000 nits peak","cpu":"MediaTek Dimensity 7300 Ultra (4 nm)","gpu":"Mali-G615 MC2","ram":"8GB / 12GB","storage":"128GB / 256GB / 512GB","camera":"50MP main (OIS) + 8MP ultra-wide + 2MP macro","front_camera":"20MP","battery":"5110mAh, 45W","os":"Android 14 (HyperOS)","weight":"185.5 g (plastic) / 190 g (PU)","thickness":"8.4 mm / 8.6 mm","sim":"Dual SIM","body":"Gorilla Glass Victus 2 front, IP68"}'::jsonb, '2026-10-12', 'https://m.gsmarena.com/xiaomi_poco_x7-ampp-13604.php', 'approx'
