  -- Xiaomi POCO F8 Pro
  update public.products set name='Xiaomi POCO F8 Pro', description='پوکو F8 Pro شیائومی با نمایشگر AMOLED ‏۶٫۵۹ اینچی، رزولوشن ۱۱۵۶×۲۵۱۰، نرخ نوسازی ۱۲۰ هرتز و روشنایی اوج ۳۵۰۰ نیت. پردازندهٔ Qualcomm Snapdragon 8 Elite (۳ نانومتر) با گرافیک Adreno 830 و رم ۱۲ گیگابایت، در نسخه‌های ۲۵۶ و ۵۱۲ گیگابایت. دوربین سه‌گانهٔ ۵۰ + ۵۰ + ۸ مگاپیکسلی، سلفی ۲۰ مگاپیکسلی، باتری ۶۲۱۰ میلی‌آمپرساعت با شارژ ۱۰۰ وات و اندروید ۱۶ با HyperOS 3. بدنه با شیشهٔ Gorilla Glass 7i، قاب آلومینیومی و مقاومت IP68، وزن ۱۹۹ گرم. رنگ‌ها: مشکی، نقره‌ای تیتانیوم و آبی. قیمت، قیمت عرضهٔ جهانی (۵۷۹ دلار) است و در فروشگاه‌ها متفاوت است.', is_active=true, price_toman=round((57900 / 100.0) * v_rate), discount_percent=0, stock=8, price_usd_cents=57900, brand='Xiaomi', specs='{"display":"6.59 inch AMOLED, 1156x2510, 120Hz, 3500 nits peak","cpu":"Qualcomm Snapdragon 8 Elite (3 nm)","gpu":"Adreno 830","ram":"12GB","storage":"256GB / 512GB","camera":"50MP + 50MP + 8MP triple camera","front_camera":"20MP","battery":"6210mAh, 100W","os":"Android 16 (HyperOS 3)","weight":"199 g","thickness":"8 mm","sim":"Dual SIM + eSIM","body":"Gorilla Glass 7i front, aluminum frame, glass back, IP68"}'::jsonb, price_checked_on='2026-10-12', source_url='https://www.fonearena.com/blog/469763/poco-f8-pro-price-specifications.html', price_note='approx' where slug='xiaomi-poco-f8-pro';
