  -- Samsung Galaxy S25 FE
  update public.products set name='Samsung Galaxy S25 FE', description='گلکسی S25 FE سامسونگ با نمایشگر Dynamic AMOLED 2X ‏۶٫۷ اینچی، رزولوشن ۱۰۸۰×۲۳۴۰ و نرخ نوسازی ۱۲۰ هرتز. پردازندهٔ Exynos 2400 (۴ نانومتر) با گرافیک Xclipse 940، رم ۸ گیگابایت و حافظهٔ ۱۲۸، ۲۵۶ یا ۵۱۲ گیگابایت. دوربین اصلی ۵۰ مگاپیکسلی با OIS، فوق‌عریض ۱۲ مگاپیکسلی و تله‌فوتو ۸ مگاپیکسلی با زوم ۳ برابر، سلفی ۱۲ مگاپیکسلی. باتری ۴۹۰۰ میلی‌آمپرساعت با شارژ سیمی ۴۵ وات و بی‌سیم ۱۵ وات، اندروید ۱۶ با One UI 8 و هفت نسخهٔ ارتقای سیستم‌عامل. وزن ۱۹۰ گرم، ضخامت ۷٫۴ میلی‌متر و مقاومت IP68. قیمت عرضهٔ آمریکا از ۶۴۹٫۹۹ دلار برای نسخهٔ ۱۲۸ گیگابایت است.', is_active=true, price_toman=round((64999 / 100.0) * v_rate), discount_percent=0, stock=9, price_usd_cents=64999, brand='Samsung', specs='{"display":"6.7 inch Dynamic AMOLED 2X, 1080x2340, 120Hz","cpu":"Samsung Exynos 2400 (4 nm)","gpu":"Xclipse 940","ram":"8GB","storage":"128GB / 256GB / 512GB","camera":"50MP main (OIS) + 12MP ultra-wide + 8MP 3x telephoto (OIS)","front_camera":"12MP","battery":"4900mAh, 45W wired, 15W wireless","os":"Android 16 (One UI 8), 7 major OS upgrades","weight":"190 g","thickness":"7.4 mm","body":"Gorilla Glass Victus+, armor aluminum frame, IP68"}'::jsonb, price_checked_on='2026-10-12', source_url='https://www.gsmarena.com/samsung_galaxy_s25_fe-review-2880.php', price_note='from' where slug='samsung-galaxy-s25-fe';
