  update public.products set name='Sony PlayStation 5 Pro', description='کنسول بازی PlayStation 5 Pro سونی با پردازندهٔ AMD Zen 2 هشت‌هسته‌ای (تا ۳٫۸۵ گیگاهرتز)، پردازندهٔ گرافیکی با ۶۰ واحد محاسباتی و حدود ۱۶٫۷ ترافلاپس، حافظهٔ ۱۶ گیگابایت GDDR6 و SSD دو ترابایتی. ارتقای تصویر با PSSR و Wi-Fi 7 دارد. درایو دیسک همراه کنسول نیست و جداگانه افزوده می‌شود. قیمت ۸۹۹٫۹۹ دلار پس از افزایش قیمت آوریل ۲۰۲۶ گزارش شده است؛ منابع دیگر قیمت متفاوتی داده‌اند و باید پیش از انتشار بررسی شود.', is_active=true, price_toman=round((89999 / 100.0) * v_rate), discount_percent=0, stock=6, price_usd_cents=89999, brand='Sony', specs='{"cpu":"AMD Zen 2, 8 cores / 16 threads, up to 3.85 GHz","gpu":"AMD RDNA, 60 compute units, about 16.7 TFLOPS","ram":"16GB GDDR6","storage":"2TB SSD","upscaling":"PSSR (PlayStation Spectral Super Resolution)","connectivity":"Wi-Fi 7","optical":"Disc drive not included (optional add-on)"}'::jsonb, price_checked_on='2026-10-12', source_url='https://tech-insider.org/ps5-pro-vs-ps5-2026/', price_note='approx' where slug='sony-playstation-5-pro';
